// Verify GitHub X-Hub-Signature-256 and filter eligible Releases & Milestones.
const crypto = require('crypto');
const item = $input.first();
const headers = item.json.headers || {};
const payload = item.json.body || {};
const rawBody = item.binary?.data ? Buffer.from(item.binary.data.data, 'base64').toString('utf8') : JSON.stringify(payload);
const secret = $env.GITHUB_WEBHOOK_SECRET;
const sigHeader = headers['x-hub-signature-256'] || '';

if (!secret || !sigHeader.startsWith('sha256=')) {
  throw new Error('Unauthorized: missing GitHub webhook signature or secret');
}
const expected = 'sha256=' + crypto.createHmac('sha256', secret).update(rawBody, 'utf8').digest('hex');
if (expected.length !== sigHeader.length || !crypto.timingSafeEqual(Buffer.from(expected), Buffer.from(sigHeader))) {
  throw new Error('Unauthorized: invalid GitHub X-Hub-Signature-256');
}

const eventType = headers['x-github-event'] || '';
const repo = payload.repository?.full_name || 'unknown/repo';
let eligible = false;
let category = 'release';
let title = '';
let summarySource = '';
let version = '';
let publishedAt = new Date().toISOString().slice(0, 10);
let sourceUrl = payload.repository?.html_url || '';
let sourceEventId = '';

if (eventType === 'release' && payload.action === 'published' && payload.release && !payload.release.draft && !payload.release.prerelease) {
  const r = payload.release;
  title = r.name || r.tag_name || '';
  summarySource = r.body || '';
  if (!/\[skip-publish\]/i.test(title + ' ' + summarySource) && !/^(fix|chore|ci|build)\b/i.test(title)) {
    eligible = true;
    category = 'release';
    version = String(r.tag_name || '').replace(/^v/, '');
    publishedAt = (r.published_at || publishedAt).slice(0, 10);
    sourceUrl = r.html_url || sourceUrl;
    sourceEventId = `${repo}#release:${r.tag_name || r.id}`;
  }
} else if (eventType === 'milestone' && payload.action === 'closed' && payload.milestone) {
  const m = payload.milestone;
  if (/\[publish\]/i.test((m.title || '') + ' ' + (m.description || ''))) {
    eligible = true;
    category = 'milestone';
    title = String(m.title || '').replace(/\[publish\]/gi, '').trim();
    summarySource = String(m.description || '').replace(/\[publish\]/gi, '').trim();
    publishedAt = (m.closed_at || publishedAt).slice(0, 10);
    sourceUrl = m.html_url || sourceUrl;
    sourceEventId = `${repo}#milestone:${m.number || m.id}`;
  }
}

if (!eligible) {
  return [];
}

return [{ json: { eligible, category, repoFullName: repo, title, summarySource, version, publishedAt, sourceUrl, sourceEventId } }];

// Prevent duplicate publication, generate concise English draft, and enforce secret/private-IP guard.
const crypto = require('crypto');
const event = $('Verify Signature & Filter Event').first().json;
const existingFiles = $input.all().map((i) => i.json.name || '');

const slugify = (s) => s.toLowerCase().replace(/[^a-z0-9]+/g, '-').replace(/^-+|-+$/g, '').slice(0, 56);
const slug = `${event.publishedAt}-${slugify(event.title)}`;
if (existingFiles.includes(`${slug}.md`)) {
  return [];
}

const forbidden = [
  /\b(?:ghp|gho|ghu|ghs|ghr)_[A-Za-z0-9]{20,}\b/,
  /\bgithub_pat_[A-Za-z0-9_]{20,}\b/,
  /\bsk-[A-Za-z0-9_-]{20,}\b/,
  /\b10\.\d{1,3}\.\d{1,3}\.\d{1,3}\b/,
  /\b192\.168\.\d{1,3}\.\d{1,3}\b/,
  /\b172\.(?:1[6-9]|2\d|3[0-1])\.\d{1,3}\.\d{1,3}\b/,
  /\b100\.(?:6[4-9]|[7-9]\d|1[0-1]\d|12[0-7])\.\d{1,3}\.\d{1,3}\b/
];
for (const re of forbidden) {
  if (re.test(event.title + '\n' + event.summarySource)) {
    throw new Error('Security guard blocked sensitive token or private IP in event payload');
  }
}

let desc = `${event.title}: ${event.summarySource.replace(/\s+/g, ' ').trim()}`;
if (desc.length < 50) desc = `${event.title} — verified ${event.category} update published on HomeLabCore.`;
if (desc.length > 230) desc = desc.slice(0, 226) + '...';

const markdown = [
  '---',
  `title: ${JSON.stringify(event.title)}`,
  `description: ${JSON.stringify(desc)}`,
  `published: "${event.publishedAt}"`,
  `category: "${event.category}"`,
  ...(event.version ? [`version: ${JSON.stringify(event.version)}`] : []),
  `sourceEventId: ${JSON.stringify(event.sourceEventId)}`,
  `sourceUrl: ${JSON.stringify(event.sourceUrl)}`,
  '---',
  '',
  event.summarySource || `Verified ${event.category} update.`,
  '',
  `Source reference: [${event.repoFullName}](${event.sourceUrl}).`
].join('\n');

const shortSlug = slug.slice(0, 34);
const sign = (action) => `${action}|${shortSlug}|` + crypto.createHmac('sha256', $env.TELEGRAM_CALLBACK_SECRET).update(`${action}|${shortSlug}`).digest('hex').slice(0, 16);

return [{
  json: {
    slug,
    filePath: `src/content/blog/${slug}.md`,
    branchName: `auton-pub/${slug}`,
    title: event.title,
    description: desc,
    sourceEventId: event.sourceEventId,
    markdownBase64: Buffer.from(markdown, 'utf8').toString('base64'),
    approveCallback: sign('approve'),
    rejectCallback: sign('reject')
  }
}];

