// Validate Telegram webhook secret token, owner user/chat ID, and HMAC callback signature.
const crypto = require('crypto');
const item = $input.first();
const headers = item.json.headers || {};
const body = item.json.body || {};
const headerToken = headers['x-telegram-bot-api-secret-token'] || '';
if (headerToken !== $env.TELEGRAM_WEBHOOK_SECRET) {
  throw new Error('Unauthorized Telegram webhook secret token');
}
const cb = body.callback_query;
if (!cb || String(cb.from?.id) !== String($env.TELEGRAM_OWNER_USER_ID) || String(cb.message?.chat?.id) !== String($env.TELEGRAM_OWNER_CHAT_ID)) {
  throw new Error('Unauthorized Telegram user or chat ID');
}
const [action, shortSlug, sig] = String(cb.data || '').split('|');
const expectedSig = crypto.createHmac('sha256', $env.TELEGRAM_CALLBACK_SECRET).update(`${action}|${shortSlug}`).digest('hex').slice(0, 16);
if (sig !== expectedSig || action !== 'approve') {
  return [];
}
return [{ json: { approved: true, shortSlug, reviewerId: cb.from.id } }];

